// Generated by scripts/gen-stdlib.mjs from src/dsl/stdlib/*.proschi; run `npm run gen:stdlib` after editing them.
/** The bundled stdlib files, in the order they are read (core.proschi first, then by name). */
export const STDLIB_SOURCES: readonly { path: string; source: string }[] = [
  { path: "stdlib/core.proschi", source: "# Proschi standard library: the root types. Bundled with the parser, so every\n# diagram sees them. The format is in docs/design/typed-components.md.\n#\n# Rules for stdlib files:\n# - Only `type` and `abstract type` blocks, blank lines and comments.\n# - A type named after a catalog tech stack (src/catalog/componentCatalog.ts)\n#   is drawn with that tech's icon and must have the kind the catalog gives it\n#   (stdlib.test.ts checks both). Every catalog tech has a type.\n# - An abstract type, or any type the catalog does not know, must not share\n#   a name or an alias with a catalog tech: the catalog name always wins.\n# - Simulation numbers (latencyMs, rps, …) go here only when they equal what\n#   sim/profiles.ts already gives the tech, so diagrams simulate as before.\n# - An op a practice problem's step already uses must have the access that\n#   step has today (dsl/access.ts); stdlib.test.ts checks it.\n# - Op names are unique along a type's chain, ignoring case: a parent's\n#   upper-case plain words (WRITE, SEND) are not repeated by its children.\n# - After editing, run `npm run gen:stdlib` to refresh sources.gen.ts.\n#\n# The top levels: Component, then Caller and Shape (clients), Annotation and\n# Group (drawing aids), Edge, Compute, DataComponent, Messaging and External.\n\nabstract type Component {\n  doc \"Anything drawn on the diagram: the root of every type.\"\n}\n\n# Clients: who sends the first request.\n\nabstract type Caller {\n  kind client\n  doc \"Whoever sends the first request: a person, a browser or an app.\"\n}\n\ntype Actor extends Caller {\n  doc \"A person who uses the system.\"\n}\n\ntype Browser extends Caller {\n  doc \"A web browser running the site's pages.\"\n}\n\ntype [Mobile App] extends Caller {\n  doc \"An iOS or Android app on the user's phone.\"\n}\n\nabstract type Shape {\n  kind client\n  doc \"A plain shape, drawn without a product icon; it simulates as a client.\"\n}\n\ntype Rectangle extends Shape {\n  doc \"A plain rectangle.\"\n}\n\ntype Circle extends Shape {\n  doc \"A plain circle.\"\n}\n\ntype Diamond extends Shape {\n  doc \"A plain diamond, often used for a decision.\"\n}\n\ntype Cylinder extends Shape {\n  doc \"A plain cylinder, the usual sketch of storage.\"\n}\n\ntype Cloud extends Shape {\n  doc \"A plain cloud shape, for the internet or a provider you do not detail.\"\n}\n\n# Drawing aids: they take no part in the simulation.\n\nabstract type Annotation {\n  kind other\n  doc \"A note on the diagram that takes no part in the simulation.\"\n}\n\ntype Note extends Annotation {\n  doc \"A note shape with text, for remarks next to the components.\"\n}\n\ntype [Text Note] extends Annotation {\n  doc \"Free text placed on the canvas.\"\n}\n\ntype [Sticky Note] extends Annotation {\n  doc \"A sticky note on the canvas.\"\n}\n\ntype Comment extends Annotation {\n  doc \"A review comment on the canvas.\"\n}\n\nabstract type Group {\n  kind other\n  doc \"A box drawn around components that belong together.\"\n}\n\ntype [Logical Group] extends Group {\n  doc \"A box around components that form one part of the design.\"\n}\n\ntype [Network Boundary] extends Group {\n  doc \"A box around components in one network, such as a VPC or a subnet.\"\n}\n\ntype [Security Zone] extends Group {\n  doc \"A box around components that share one trust level.\"\n}\n\ntype [Service Group] extends Group {\n  doc \"A box around the components one team or service owns.\"\n}\n" },
  { path: "stdlib/cloud-aws.proschi", source: "# Proschi standard library: Amazon Web Services. The rules are in core.proschi.\n\n# Edge\n\ntype [AWS CloudFront] extends CDN {\n  op write MESSAGE   # forwards a WebSocket message\n  op write CreateInvalidation\n  doc \"Amazon CloudFront, the CDN of AWS.\"\n}\n\ntype [AWS Route53] extends DNS {\n  op write ChangeResourceRecordSets\n  doc \"Amazon Route 53, the DNS service of AWS, with health checks and latency routing.\"\n}\n\ntype [AWS Load Balancer] extends [Load Balancer] {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"Elastic Load Balancing: an application (L7) or network (L4) load balancer on AWS.\"\n}\n\ntype [AWS API Gateway] extends [API Gateway] {\n  doc \"Amazon API Gateway, the managed API front door of AWS.\"\n}\n\ntype [AWS WAF] extends WAF {\n  doc \"AWS WAF, the web application firewall in front of CloudFront, load balancers and API Gateway.\"\n}\n\ntype [AWS Global Accelerator] extends Edge {\n  doc \"AWS Global Accelerator: anycast addresses that carry traffic over the AWS network to the nearest healthy region.\"\n}\n\n# Compute\n\ntype [AWS EC2] extends VM {\n  doc \"Amazon EC2, virtual machines on AWS.\"\n}\n\ntype [AWS ECS] extends Docker {\n  doc \"Amazon ECS, which runs containers on AWS.\"\n}\n\ntype [AWS Fargate] extends Docker {\n  doc \"AWS Fargate, containers on AWS without servers to manage.\"\n}\n\ntype [AWS EKS] extends Kubernetes {\n  doc \"Amazon EKS, managed Kubernetes on AWS.\"\n}\n\ntype [AWS Lambda] extends Function {\n  doc \"AWS Lambda, functions that run per request or event on AWS.\"\n}\n\n# Data\n\ntype [AWS RDS] extends Database {\n  doc \"Amazon RDS, managed relational databases on AWS (PostgreSQL, MySQL and others).\"\n}\n\ntype [AWS Aurora] extends Database {\n  doc \"Amazon Aurora, the AWS relational database compatible with PostgreSQL and MySQL, on shared distributed storage.\"\n}\n\ntype [AWS DynamoDB] extends DynamoDB {\n  doc \"Amazon DynamoDB, the managed key-value and document database of AWS.\"\n}\n\ntype [AWS DocumentDB] extends MongoDB {\n  doc \"Amazon DocumentDB, the AWS document database compatible with MongoDB.\"\n}\n\ntype [AWS Keyspaces] extends Cassandra {\n  doc \"Amazon Keyspaces, the AWS wide-column database compatible with Cassandra.\"\n}\n\ntype [AWS Neptune] extends GraphNoSql {\n  doc \"Amazon Neptune, the graph database of AWS.\"\n}\n\ntype [AWS ElastiCache] extends Redis {\n  doc \"Amazon ElastiCache, managed Redis, Valkey or Memcached on AWS.\"\n}\n\ntype [AWS OpenSearch] extends OpenSearch {\n  doc \"Amazon OpenSearch Service, managed OpenSearch on AWS.\"\n}\n\ntype [AWS Redshift] extends [Data Warehouse] {\n  doc \"Amazon Redshift, the data warehouse of AWS.\"\n}\n\ntype [AWS Athena] extends [Data Warehouse] {\n  op read  StartQueryExecution, GetQueryExecution, GetQueryResults\n  doc \"Amazon Athena, SQL queries over files in S3.\"\n}\n\ntype [AWS S3] extends [Object Storage] {\n  op read  GetObject, HeadObject, ListObjectsV2, ListObjects, GetObjectTagging, GetObjectAcl\n  op read  ListMultipartUploads, ListParts, SelectObjectContent, HeadBucket, ListBuckets\n  op write PutObject, CopyObject, DeleteObject, DeleteObjects, RestoreObject, PutObjectTagging, PutObjectAcl\n  op write CreateMultipartUpload, UploadPart, UploadPartCopy, CompleteMultipartUpload, AbortMultipartUpload\n  op write CreateBucket, DeleteBucket\n  doc \"Amazon S3, the object storage of AWS.\"\n}\n\ntype [AWS EBS] extends BlockStorage {\n  doc \"Amazon EBS, block volumes for EC2 instances.\"\n}\n\ntype [AWS EFS] extends SharedFileSystem {\n  doc \"Amazon EFS, a shared NFS file system on AWS.\"\n}\n\n# Messaging\n\ntype [AWS SQS] extends SQS {\n  doc \"Amazon SQS, the managed message queue of AWS.\"\n}\n\ntype [AWS SNS] extends [Message Broker] {\n  op write PublishBatch, CreateTopic, DeleteTopic\n  doc \"Amazon SNS, the pub/sub topics of AWS that fan out to queues, functions and phones.\"\n}\n\ntype [AWS EventBridge] extends [Message Broker] {\n  op write PutEvents, PutRule, PutTargets\n  doc \"Amazon EventBridge, the AWS event bus that routes events by rules.\"\n}\n\ntype [AWS Kinesis] extends [Message Broker] {\n  op read  GetRecords, GetShardIterator, SubscribeToShard, DescribeStream, ListShards\n  op write PutRecord, PutRecords\n  doc \"Amazon Kinesis Data Streams, the partitioned stream of AWS.\"\n}\n\ntype [AWS MSK] extends Kafka {\n  doc \"Amazon MSK, managed Kafka on AWS.\"\n}\n\n# External\n\ntype [AWS SES] extends [Email Service] {\n  op write SendEmail, SendRawEmail, SendBulkEmail\n  doc \"Amazon SES, the email sending service of AWS.\"\n}\n\ntype [AWS Cognito] extends [Auth Service] {\n  op read  GetUser\n  op write InitiateAuth, RespondToAuthChallenge, SignUp, ConfirmSignUp, GlobalSignOut\n  doc \"Amazon Cognito, user sign-up and sign-in on AWS.\"\n}\n" },
  { path: "stdlib/cloud-azure.proschi", source: "# Proschi standard library: Microsoft Azure. The rules are in core.proschi.\n\n# Edge\n\ntype [Azure CDN] extends CDN {\n  doc \"Azure CDN, the content delivery network of Azure.\"\n}\n\ntype [Azure Front Door] extends CDN {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"Azure Front Door, Azure's global entry point: CDN, load balancing and WAF at the edge.\"\n}\n\ntype [Azure DNS] extends DNS {\n  doc \"Azure DNS, the DNS service of Azure.\"\n}\n\ntype [Azure Load Balancer] extends [Load Balancer] {\n  doc \"Azure Load Balancer, the L4 load balancer of Azure.\"\n}\n\ntype [Azure Application Gateway] extends [Load Balancer] {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"Azure Application Gateway, the L7 load balancer of Azure, with an optional WAF.\"\n}\n\ntype [Azure API Management] extends [API Gateway] {\n  doc \"Azure API Management, the API gateway and developer portal of Azure.\"\n}\n\n# Compute\n\ntype [Azure VM] extends VM {\n  doc \"Azure Virtual Machines, virtual machines on Azure.\"\n}\n\ntype [Azure AKS] extends Kubernetes {\n  doc \"Azure Kubernetes Service, managed Kubernetes on Azure.\"\n}\n\ntype [Azure Container Instances] extends Docker {\n  doc \"Azure Container Instances, containers on Azure without servers to manage.\"\n}\n\ntype [Azure App Service] extends Platform {\n  doc \"Azure App Service, Azure's managed platform for web apps and APIs.\"\n}\n\ntype [Azure Functions] extends Function {\n  doc \"Azure Functions, functions that run per request or event on Azure.\"\n}\n\ntype [Azure Logic Apps] extends Function {\n  doc \"Azure Logic Apps, workflows of connectors that run on triggers.\"\n}\n\n# Data\n\ntype [Azure SQL] extends [SQL Server] {\n  doc \"Azure SQL Database, managed SQL Server on Azure.\"\n}\n\ntype [Azure Database for PostgreSQL] extends PostgreSQL {\n  doc \"Azure Database for PostgreSQL, managed PostgreSQL on Azure.\"\n}\n\ntype [Azure Database for MySQL] extends MySQL {\n  doc \"Azure Database for MySQL, managed MySQL on Azure.\"\n}\n\ntype [Azure Cosmos DB] extends DocumentNoSql {\n  op read  ReadItem, ReadMany, QueryItems, ReadChangeFeed\n  op write CreateItem, UpsertItem, ReplaceItem, PatchItem, DeleteItem, TransactionalBatch\n  doc \"Azure Cosmos DB, Azure's globally distributed multi-model database.\"\n}\n\ntype [Azure Cache for Redis] extends Redis {\n  doc \"Azure Cache for Redis, managed Redis on Azure.\"\n}\n\ntype [Azure AI Search] extends [Search Engine] {\n  doc \"Azure AI Search, the managed search service of Azure, with vector search.\"\n}\n\ntype [Azure Blob Storage] extends [Object Storage] {\n  op read  GetBlob, GetBlobProperties, GetBlobMetadata, GetBlockList, ListBlobs, ListContainers\n  op write PutBlob, PutBlock, PutBlockList, PutPage, AppendBlock, CopyBlob, DeleteBlob\n  op write SetBlobMetadata, SetBlobProperties, SnapshotBlob, LeaseBlob, CreateContainer, DeleteContainer\n  doc \"Azure Blob Storage, the object storage of Azure.\"\n}\n\ntype [Azure Files] extends SharedFileSystem {\n  doc \"Azure Files, managed SMB and NFS file shares on Azure.\"\n}\n\ntype [Azure Disk Storage] extends BlockStorage {\n  doc \"Azure Managed Disks, block volumes for Azure virtual machines.\"\n}\n\n# Messaging\n\ntype [Azure Queue Storage] extends [Message Queue] {\n  op read  GetMessages, PeekMessages\n  op write PutMessage, UpdateMessage, DeleteMessage, ClearMessages\n  doc \"Azure Queue Storage, simple message queues in an Azure storage account.\"\n}\n\ntype [Azure Service Bus] extends [Message Broker] {\n  op read  ReceiveMessages, PeekMessages\n  op write SendMessages, CompleteMessage, AbandonMessage, DeadLetterMessage, DeferMessage, ScheduleMessages\n  doc \"Azure Service Bus, Azure's enterprise broker of queues and topics.\"\n}\n\ntype [Azure Event Hubs] extends [Message Broker] {\n  op read  ReceiveEvents\n  op write SendEvents, UpdateCheckpoint\n  doc \"Azure Event Hubs, Azure's partitioned event stream, with a Kafka endpoint.\"\n}\n\ntype [Azure Event Grid] extends [Message Broker] {\n  op write PublishEvents\n  doc \"Azure Event Grid, Azure's event routing service.\"\n}\n" },
  { path: "stdlib/cloud-cloudflare.proschi", source: "# Proschi standard library: Cloudflare. The rules are in core.proschi.\n\ntype Cloudflare extends CDN {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"Cloudflare, the CDN and edge network in front of the origin.\"\n}\n\ntype [Cloudflare Workers] extends Function {\n  doc \"Cloudflare Workers, functions that run at Cloudflare's edge locations.\"\n}\n\ntype [Cloudflare R2] extends [AWS S3] {\n  doc \"Cloudflare R2, object storage with the S3 API and no egress fees.\"\n}\n" },
  { path: "stdlib/cloud-gcp.proschi", source: "# Proschi standard library: Google Cloud. The rules are in core.proschi.\n\n# Edge\n\ntype [GCP Cloud CDN] extends CDN {\n  doc \"Cloud CDN, the CDN of Google Cloud.\"\n}\n\ntype [GCP Cloud DNS] extends DNS {\n  doc \"Cloud DNS, the DNS service of Google Cloud.\"\n}\n\ntype [GCP Load Balancing] extends [Load Balancer] {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"Cloud Load Balancing, Google Cloud's global and regional load balancers.\"\n}\n\ntype [GCP Apigee] extends [API Gateway] {\n  doc \"Apigee, Google Cloud's API management platform.\"\n}\n\n# Compute\n\ntype [GCP Compute Engine] extends VM {\n  doc \"Compute Engine, virtual machines on Google Cloud.\"\n}\n\ntype [GCP GKE] extends Kubernetes {\n  doc \"Google Kubernetes Engine, managed Kubernetes on Google Cloud.\"\n}\n\ntype [GCP Cloud Functions] extends Function {\n  doc \"Cloud Functions, functions that run per request or event on Google Cloud.\"\n}\n\ntype [GCP Cloud Run] extends Function {\n  doc \"Cloud Run, containers that run per request and scale to zero on Google Cloud.\"\n}\n\ntype [GCP App Engine] extends Function {\n  doc \"App Engine, Google Cloud's managed platform for web apps.\"\n}\n\n# Data\n\ntype [GCP Cloud SQL] extends Database {\n  doc \"Cloud SQL, managed PostgreSQL, MySQL and SQL Server on Google Cloud.\"\n}\n\ntype [GCP Spanner] extends DistributedSql {\n  op read  ExecuteSql, ExecuteStreamingSql, StreamingRead, BeginTransaction\n  op write ExecuteBatchDml\n  doc \"Spanner, Google Cloud's globally distributed relational database with external consistency.\"\n}\n\ntype [GCP Firestore] extends DocumentNoSql {\n  op read  GetDocument, ListDocuments, BatchGetDocuments, RunQuery, RunAggregationQuery, Listen\n  op write CreateDocument, UpdateDocument, DeleteDocument, BatchWrite, Commit, BeginTransaction\n  doc \"Firestore, Google Cloud's serverless document database.\"\n}\n\ntype [GCP Bigtable] extends WideColumnNoSql {\n  op read  ReadRows, SampleRowKeys\n  op write MutateRow, MutateRows, CheckAndMutateRow, ReadModifyWriteRow\n  doc \"Bigtable, Google Cloud's wide-column database for large, low-latency workloads.\"\n}\n\ntype [GCP Memorystore] extends Redis {\n  doc \"Memorystore, managed Redis and Memcached on Google Cloud.\"\n}\n\ntype [GCP BigQuery] extends [Data Warehouse] {\n  doc \"BigQuery, Google Cloud's serverless data warehouse.\"\n}\n\ntype [GCP Cloud Storage] extends [Object Storage] {\n  op write Insert, Patch, Update, Copy, Compose, Rewrite\n  doc \"Cloud Storage, the object storage of Google Cloud.\"\n}\n\ntype [GCP Persistent Disk] extends BlockStorage {\n  doc \"Persistent Disk, block volumes for Compute Engine.\"\n}\n\n# Messaging\n\ntype [GCP Pub/Sub] extends [Message Broker] {\n  op read  Pull, StreamingPull\n  op write Acknowledge, ModifyAckDeadline, CreateTopic, CreateSubscription, Seek\n  doc \"Pub/Sub, Google Cloud's global messaging service of topics and subscriptions.\"\n}\n" },
  { path: "stdlib/compute.proschi", source: "# Proschi standard library: compute, the code you run. The rules are in\n# core.proschi.\n\nabstract type Compute {\n  kind service\n  protocol HTTP\n  status 100, 101, 102, 103\n  status 200, 201, 202, 203, 204, 205, 206, 207, 208, 226\n  status 300, 301, 302, 303, 304, 307, 308\n  status 400, 401, 402, 403, 404, 405, 406, 407, 408, 409, 410, 411, 412, 413, 414, 415, 416, 417, 418\n  status 421, 422, 423, 424, 425, 426, 428, 429, 431, 451\n  status 500, 501, 502, 503, 504, 505, 506, 507, 508, 510, 511\n  header Accept, Accept-Encoding, Accept-Language, Accept-Ranges, Age, Allow, Authorization\n  header Cache-Control, Connection, Content-Disposition, Content-Encoding, Content-Language\n  header Content-Length, Content-Range, Content-Type, Cookie, Date, ETag, Expires, Host\n  header If-Match, If-Modified-Since, If-None-Match, If-Range, If-Unmodified-Since, Last-Modified\n  header Link, Location, Origin, Range, Referer, Retry-After, Server, Set-Cookie, User-Agent, Vary\n  header Upgrade, WWW-Authenticate, Proxy-Authorization, Strict-Transport-Security, Content-Security-Policy\n  header Access-Control-Allow-Origin, Access-Control-Allow-Methods, Access-Control-Allow-Headers\n  header Access-Control-Allow-Credentials, Access-Control-Max-Age, Access-Control-Request-Method\n  header Forwarded, X-Forwarded-For, X-Forwarded-Host, X-Forwarded-Proto, X-Real-IP\n  header X-Request-Id, X-Correlation-Id, Traceparent, Tracestate, Idempotency-Key\n  header X-RateLimit-Limit, X-RateLimit-Remaining, X-RateLimit-Reset, RateLimit-Limit, RateLimit-Remaining, RateLimit-Reset\n  header X-API-Key, X-Content-Type-Options, X-Frame-Options, Sec-WebSocket-Key, Sec-WebSocket-Accept, Sec-WebSocket-Protocol\n  doc \"Code you run: a service, a worker, a function or the platform it runs on; its own requests are named freely.\"\n}\n\ntype Service extends Compute {\n  doc \"A program you run that answers requests, whatever it is written in.\"\n}\n\ntype Worker extends Compute {\n  doc \"A background program that takes jobs or events from a queue and processes them.\"\n}\n\n# Interfaces.\n\nabstract type HttpService extends Service {\n  op read  GET, HEAD, OPTIONS, TRACE, CONNECT\n  op write POST, PUT, PATCH, DELETE\n  doc \"A service whose requests are HTTP methods: GET, HEAD and OPTIONS read, POST, PUT, PATCH and DELETE write.\"\n}\n\ntype [REST API] extends HttpService {\n  doc \"A service with a REST interface: resources over HTTP methods and status codes.\"\n}\n\ntype GraphQL extends HttpService {\n  protocol GraphQL\n  op read  query, subscription\n  op write mutation\n  doc \"A service with a GraphQL interface: queries read, mutations write.\"\n}\n\ntype gRPC extends Service {\n  protocol gRPC\n  doc \"A service with a gRPC interface: typed calls over HTTP/2, named by its own .proto file.\"\n}\n\ntype WebSocket extends Service {\n  protocol WebSocket\n  doc \"A service that keeps a WebSocket open to each client and pushes messages both ways, named freely.\"\n}\n\ntype [SOAP API] extends Service {\n  protocol SOAP\n  doc \"A service with a SOAP interface: XML messages over HTTP.\"\n}\n\n# Languages and frameworks: a service written in it.\n\ntype Java extends Service {\n  doc \"A service on the JVM, written in Java.\"\n}\n\ntype [Spring Boot] extends Java {\n  doc \"A service built with Spring Boot.\"\n}\n\ntype Kotlin extends Service {\n  doc \"A service written in Kotlin.\"\n}\n\ntype Go extends Service {\n  doc \"A service written in Go.\"\n}\n\ntype [Node.js] extends Service {\n  doc \"A service on Node.js, written in JavaScript or TypeScript.\"\n}\n\ntype Python extends Service {\n  doc \"A service written in Python.\"\n}\n\ntype Django extends Python {\n  doc \"A service built with Django.\"\n}\n\ntype FastAPI extends Python {\n  doc \"A service built with FastAPI.\"\n}\n\ntype Flask extends Python {\n  doc \"A service built with Flask.\"\n}\n\ntype [Ruby on Rails] extends Service {\n  doc \"A service built with Ruby on Rails.\"\n}\n\ntype [.NET] extends Service {\n  doc \"A service on .NET, written in C#.\"\n}\n\ntype PHP extends Service {\n  doc \"A service written in PHP.\"\n}\n\ntype Rust extends Service {\n  doc \"A service written in Rust.\"\n}\n\ntype Elixir extends Service {\n  doc \"A service written in Elixir, on the Erlang VM.\"\n}\n\n# Where services run.\n\nabstract type Platform extends Compute {\n  doc \"Where a service runs, drawn as the platform: it answers like the service on it.\"\n}\n\ntype VM extends Platform {\n  doc \"A virtual machine running the service.\"\n}\n\ntype Docker extends Platform {\n  doc \"A container running the service.\"\n}\n\ntype Kubernetes extends Platform {\n  doc \"Pods on a Kubernetes cluster running the service.\"\n}\n\n# Functions.\n\ntype Function extends Compute {\n  kind function\n  doc \"A serverless function: runs per request or event and scales to zero.\"\n}\n" },
  { path: "stdlib/data.proschi", source: "# Proschi standard library: components that keep data. Queues and brokers\n# are in messaging.proschi. The rules are in core.proschi.\n\nabstract type DataComponent {\n  op read  READ, FETCH, LOOKUP\n  op write WRITE, SAVE, STORE, RECORD, MARK, RESERVE, HOLD, BOOK\n  doc \"A component that keeps data: a database, cache, search index, warehouse or bucket.\"\n}\n\n# Relational databases.\n\ntype Database extends DataComponent {\n  kind database\n  protocol SQL\n  op read  SELECT, WITH, EXPLAIN, SHOW, BEGIN, ROLLBACK\n  op write INSERT, UPDATE, DELETE, UPSERT, MERGE, TRUNCATE, COMMIT, LOCK\n  op write CREATE, ALTER, DROP\n  doc \"A relational database queried with SQL, whose product does not matter.\"\n}\n\ntype PostgreSQL extends Database {\n  op read  LISTEN\n  op write NOTIFY, COPY, VACUUM\n  doc \"PostgreSQL, the open source relational database.\"\n}\n\ntype MySQL extends Database {\n  op write REPLACE\n  doc \"MySQL, the open source relational database.\"\n}\n\ntype MariaDB extends MySQL {\n  doc \"MariaDB, the community fork of MySQL.\"\n}\n\ntype SQLite extends Database {\n  doc \"SQLite, the embedded relational database in a single file.\"\n}\n\ntype Oracle extends Database {\n  doc \"Oracle Database, the commercial relational database.\"\n}\n\ntype [SQL Server] extends Database {\n  doc \"Microsoft SQL Server, the commercial relational database.\"\n}\n\ntype TimescaleDB extends PostgreSQL {\n  kind analytics\n  doc \"TimescaleDB, PostgreSQL extended for time series.\"\n}\n\nabstract type DistributedSql extends Database {\n  doc \"A relational database that shards and replicates itself across nodes, keeping transactions.\"\n}\n\ntype CockroachDB extends DistributedSql {\n  doc \"CockroachDB, a distributed SQL database that speaks the PostgreSQL protocol.\"\n}\n\ntype YugabyteDB extends DistributedSql {\n  doc \"YugabyteDB, a distributed SQL database compatible with PostgreSQL.\"\n}\n\ntype TiDB extends DistributedSql {\n  doc \"TiDB, a distributed SQL database compatible with MySQL.\"\n}\n\ntype Vitess extends DistributedSql {\n  doc \"Vitess, which shards MySQL behind one SQL endpoint.\"\n}\n\n# NoSQL databases.\n\ntype [NoSQL Database] extends DataComponent {\n  kind database\n  op read  GET\n  op write PUT, SET, DELETE\n  doc \"A non-relational database that partitions data by key, whose product does not matter.\"\n}\n\ntype DynamoDB extends [NoSQL Database] {\n  op read  GetItem, BatchGetItem, Query, Scan, TransactGetItems, DescribeTable\n  op write PutItem, UpdateItem, DeleteItem, BatchWriteItem, TransactWriteItems\n  op write ExecuteStatement, CreateTable, UpdateTable, DeleteTable\n  doc \"DynamoDB, the managed key-value and document database: reads by key or partition, a Scan reads the whole table.\"\n}\n\nabstract type DocumentNoSql extends [NoSQL Database] {\n  doc \"A NoSQL database that stores JSON-like documents and queries their fields.\"\n}\n\ntype MongoDB extends DocumentNoSql {\n  op read  find, findOne, aggregate, countDocuments, estimatedDocumentCount, distinct, watch\n  op write insertOne, insertMany, updateOne, updateMany, replaceOne, deleteOne, deleteMany\n  op write findOneAndUpdate, findOneAndReplace, findOneAndDelete, bulkWrite, createIndex\n  doc \"MongoDB, the document database.\"\n}\n\ntype CouchDB extends DocumentNoSql {\n  doc \"Apache CouchDB, a document database with an HTTP API and multi-primary replication.\"\n}\n\ntype Couchbase extends DocumentNoSql {\n  op read  lookupIn, exists, query\n  op write upsert, insert, replace, remove, mutateIn, touch, increment, decrement\n  doc \"Couchbase, a document database with a built-in cache.\"\n}\n\nabstract type WideColumnNoSql extends [NoSQL Database] {\n  doc \"A NoSQL database of rows with many columns, partitioned by key and sorted within a partition.\"\n}\n\ntype Cassandra extends WideColumnNoSql {\n  protocol CQL\n  op read  SELECT\n  op write INSERT, UPDATE, DELETE, BATCH, TRUNCATE\n  doc \"Apache Cassandra, the wide-column database queried with CQL.\"\n}\n\ntype ScyllaDB extends Cassandra {\n  doc \"ScyllaDB, a Cassandra-compatible database written in C++.\"\n}\n\ntype HBase extends WideColumnNoSql {\n  op read  Scan, Exists\n  op write Increment, Append, CheckAndMutate\n  doc \"Apache HBase, the wide-column database on HDFS.\"\n}\n\nabstract type GraphNoSql extends [NoSQL Database] {\n  protocol Cypher\n  op read  MATCH, OPTIONAL, RETURN, CALL\n  op write CREATE, MERGE, DELETE, DETACH, SET, REMOVE\n  doc \"A graph database: nodes and relationships, queried by pattern.\"\n}\n\ntype Neo4j extends GraphNoSql {\n  doc \"Neo4j, the graph database queried with Cypher.\"\n}\n\nabstract type CoordinationStore extends DataComponent {\n  kind database\n  doc \"A small, strongly consistent store for configuration, leader election and locks.\"\n}\n\ntype etcd extends CoordinationStore {\n  op read  Range, Watch, LeaseTimeToLive\n  op write Put, DeleteRange, Txn, Compact, LeaseGrant, LeaseRevoke, LeaseKeepAlive\n  doc \"etcd, the consistent key-value store behind Kubernetes.\"\n}\n\ntype ZooKeeper extends CoordinationStore {\n  op read  getData, getChildren, exists, getACL, sync\n  op write create, setData, delete, setACL, multi\n  doc \"Apache ZooKeeper, the coordination service of znodes and watches.\"\n}\n\n# Caches.\n\ntype Cache extends DataComponent {\n  kind cache\n  op read  GET, MGET\n  op write SET, DELETE, EXPIRE\n  doc \"An in-memory key-value cache, whose product does not matter.\"\n}\n\ntype Redis extends Cache {\n  protocol RESP\n  # Strings\n  op read  GETRANGE, STRLEN\n  op write SETNX, SETEX, PSETEX, GETSET, GETDEL, GETEX, MSET, MSETNX, APPEND, SETRANGE\n  op write INCR, INCRBY, INCRBYFLOAT, DECR, DECRBY\n  # Keys\n  op read  EXISTS, TTL, PTTL, TYPE, KEYS, SCAN\n  op write DEL, UNLINK, PEXPIRE, EXPIREAT, PEXPIREAT, PERSIST, RENAME, COPY\n  # Hashes\n  op read  HGET, HMGET, HGETALL, HEXISTS, HKEYS, HVALS, HLEN, HSCAN\n  op write HSET, HSETNX, HMSET, HDEL, HINCRBY, HINCRBYFLOAT\n  # Lists\n  op read  LRANGE, LLEN, LINDEX\n  op write LPUSH, RPUSH, LPUSHX, RPUSHX, LPOP, RPOP, BLPOP, BRPOP, LSET, LREM, LTRIM, LINSERT, LMOVE, BLMOVE\n  # Sets\n  op read  SMEMBERS, SISMEMBER, SMISMEMBER, SCARD, SRANDMEMBER, SINTER, SUNION, SDIFF, SSCAN\n  op write SADD, SREM, SPOP, SMOVE, SINTERSTORE, SUNIONSTORE, SDIFFSTORE\n  # Sorted sets\n  op read  ZRANGE, ZREVRANGE, ZRANGEBYSCORE, ZREVRANGEBYSCORE, ZRANGEBYLEX, ZSCORE, ZMSCORE\n  op read  ZRANK, ZREVRANK, ZCARD, ZCOUNT, ZSCAN\n  op write ZADD, ZREM, ZINCRBY, ZPOPMIN, ZPOPMAX, BZPOPMIN, BZPOPMAX, ZREMRANGEBYSCORE, ZREMRANGEBYRANK\n  op write ZUNIONSTORE, ZINTERSTORE, ZRANGESTORE\n  # Bitmaps and HyperLogLog\n  op read  GETBIT, BITCOUNT, BITPOS, PFCOUNT\n  op write SETBIT, BITOP, PFADD, PFMERGE\n  # Geo\n  op read  GEOSEARCH, GEODIST, GEOPOS, GEOHASH, GEORADIUS, GEORADIUSBYMEMBER\n  op write GEOADD, GEOSEARCHSTORE\n  # Pub/sub\n  op read  SUBSCRIBE, PSUBSCRIBE, UNSUBSCRIBE, PUNSUBSCRIBE, SSUBSCRIBE\n  op write PUBLISH, SPUBLISH\n  # Streams\n  op read  XREAD, XREADGROUP, XRANGE, XREVRANGE, XLEN, XPENDING, XINFO\n  op write XADD, XACK, XCLAIM, XAUTOCLAIM, XDEL, XTRIM, XGROUP\n  # Transactions and scripts\n  op read  MULTI, WATCH, UNWATCH, DISCARD, PING\n  op write EXEC, EVAL, EVALSHA, FCALL\n  doc \"Redis, the in-memory data store, used as a cache.\"\n}\n\ntype Valkey extends Redis {\n  doc \"Valkey, the open source fork of Redis.\"\n}\n\ntype KeyDB extends Redis {\n  doc \"KeyDB, a multithreaded fork of Redis.\"\n}\n\ntype Dragonfly extends Redis {\n  doc \"Dragonfly, an in-memory store compatible with Redis.\"\n}\n\ntype Memcached extends Cache {\n  op read  GETS\n  op write ADD, REPLACE, APPEND, PREPEND, CAS, INCR, DECR, TOUCH, GAT, GATS, FLUSH_ALL\n  doc \"Memcached, the simple distributed in-memory cache.\"\n}\n\ntype Hazelcast extends Cache {\n  doc \"Hazelcast, the in-memory data grid.\"\n}\n\ntype Aerospike extends Cache {\n  doc \"Aerospike, the key-value store tuned for memory and flash.\"\n}\n\n# Search.\n\ntype [Search Engine] extends DataComponent {\n  kind search\n  op read  Search, KNN\n  op write Index, Upsert, Delete\n  doc \"A full-text search index, whose product does not matter.\"\n}\n\ntype Elasticsearch extends [Search Engine] {\n  op read  Get, Mget, Count, MultiSearch, Scroll, Explain, _search, _msearch, _count\n  op write Bulk, Update, Create, UpdateByQuery, DeleteByQuery, Reindex, Refresh, _bulk, _doc, _update\n  doc \"Elasticsearch, the distributed search engine on Lucene.\"\n}\n\ntype OpenSearch extends Elasticsearch {\n  doc \"OpenSearch, the open source fork of Elasticsearch.\"\n}\n\ntype Solr extends [Search Engine] {\n  doc \"Apache Solr, the search server on Lucene.\"\n}\n\ntype Meilisearch extends [Search Engine] {\n  doc \"Meilisearch, a fast search engine for search-as-you-type.\"\n}\n\ntype Typesense extends [Search Engine] {\n  doc \"Typesense, an in-memory search engine that tolerates typos.\"\n}\n\ntype Algolia extends [Search Engine] {\n  doc \"Algolia, the hosted search API.\"\n}\n\n# Analytics.\n\ntype [Data Warehouse] extends DataComponent {\n  kind analytics\n  protocol SQL\n  op read  SELECT, WITH, EXPLAIN, SHOW\n  op write INSERT, UPDATE, DELETE, UPSERT, MERGE, COPY, TRUNCATE, CREATE, DROP\n  doc \"A column store for analytical SQL over large data, whose product does not matter.\"\n}\n\ntype Snowflake extends [Data Warehouse] {\n  doc \"Snowflake, the cloud data warehouse.\"\n}\n\ntype ClickHouse extends [Data Warehouse] {\n  doc \"ClickHouse, the column-oriented OLAP database.\"\n}\n\ntype [Apache Druid] extends [Data Warehouse] {\n  doc \"Apache Druid, the real-time analytics database.\"\n}\n\ntype [Apache Pinot] extends [Data Warehouse] {\n  doc \"Apache Pinot, the real-time OLAP store for user-facing analytics.\"\n}\n\ntype Databricks extends [Data Warehouse] {\n  doc \"Databricks, the lakehouse platform on Spark.\"\n}\n\nabstract type TimeSeriesStore extends DataComponent {\n  kind analytics\n  op read  QUERY, SELECT\n  op write INSERT\n  doc \"A database of timestamped measurements, queried over time ranges.\"\n}\n\ntype InfluxDB extends TimeSeriesStore {\n  doc \"InfluxDB, the time series database.\"\n}\n\ntype Prometheus extends TimeSeriesStore {\n  doc \"Prometheus, the monitoring system and its time series store.\"\n}\n\n# Files and objects.\n\ntype [Object Storage] extends DataComponent {\n  kind storage\n  protocol HTTP\n  op read  GET, HEAD, LIST\n  op write PUT, DELETE, UPLOAD\n  doc \"A bucket of objects (files) by key, whose product does not matter.\"\n}\n\ntype MinIO extends [AWS S3] {\n  doc \"MinIO, the self-hosted object storage with the S3 API.\"\n}\n\ntype Ceph extends [Object Storage] {\n  doc \"Ceph, the distributed object, block and file storage.\"\n}\n\nabstract type SharedFileSystem extends DataComponent {\n  kind storage\n  op read  OPEN, LIST\n  op write APPEND\n  doc \"A file system many machines mount at once.\"\n}\n\ntype HDFS extends SharedFileSystem {\n  doc \"HDFS, the Hadoop distributed file system.\"\n}\n\nabstract type BlockStorage extends DataComponent {\n  kind storage\n  doc \"A disk attached to one machine.\"\n}\n" },
  { path: "stdlib/edge.proschi", source: "# Proschi standard library: the edge, between the clients and the services.\n# The rules are in core.proschi.\n\nabstract type Edge {\n  kind edge\n  doc \"What a request passes through before it reaches a service: DNS, a CDN, a load balancer or a gateway.\"\n}\n\nabstract type HttpEdge extends Edge {\n  protocol HTTP\n  op read  GET, HEAD, OPTIONS, TRACE, CONNECT\n  op write POST, PUT, PATCH, DELETE\n  status 100, 101, 102, 103\n  status 200, 201, 202, 203, 204, 205, 206, 207, 208, 226\n  status 300, 301, 302, 303, 304, 307, 308\n  status 400, 401, 402, 403, 404, 405, 406, 407, 408, 409, 410, 411, 412, 413, 414, 415, 416, 417, 418\n  status 421, 422, 423, 424, 425, 426, 428, 429, 431, 451\n  status 500, 501, 502, 503, 504, 505, 506, 507, 508, 510, 511\n  header Accept, Accept-Encoding, Accept-Language, Accept-Ranges, Age, Allow, Authorization\n  header Cache-Control, Connection, Content-Disposition, Content-Encoding, Content-Language\n  header Content-Length, Content-Range, Content-Type, Cookie, Date, ETag, Expires, Host\n  header If-Match, If-Modified-Since, If-None-Match, If-Range, If-Unmodified-Since, Last-Modified\n  header Link, Location, Origin, Range, Referer, Retry-After, Server, Set-Cookie, User-Agent, Vary\n  header Upgrade, WWW-Authenticate, Proxy-Authorization, Strict-Transport-Security, Content-Security-Policy\n  header Access-Control-Allow-Origin, Access-Control-Allow-Methods, Access-Control-Allow-Headers\n  header Access-Control-Allow-Credentials, Access-Control-Max-Age, Access-Control-Request-Method\n  header Forwarded, X-Forwarded-For, X-Forwarded-Host, X-Forwarded-Proto, X-Real-IP\n  header X-Request-Id, X-Correlation-Id, Traceparent, Tracestate, Idempotency-Key\n  header X-RateLimit-Limit, X-RateLimit-Remaining, X-RateLimit-Reset, RateLimit-Limit, RateLimit-Remaining, RateLimit-Reset\n  header X-API-Key, X-Content-Type-Options, X-Frame-Options, Sec-WebSocket-Key, Sec-WebSocket-Accept, Sec-WebSocket-Protocol\n  doc \"An edge component that takes HTTP requests and passes them on.\"\n}\n\ntype DNS extends Edge {\n  kind dns\n  protocol DNS\n  op read  QUERY, RESOLVE\n  op write UPDATE\n  doc \"A DNS service: turns a host name into the addresses to connect to.\"\n}\n\ntype CDN extends HttpEdge {\n  kind cdn\n  op write PURGE\n  doc \"A content delivery network: caches responses at edge locations near the users.\"\n}\n\ntype [Load Balancer] extends HttpEdge {\n  kind loadbalancer\n  doc \"Spreads requests over the replicas behind it and stops sending to unhealthy ones.\"\n}\n\ntype [API Gateway] extends HttpEdge {\n  op write MESSAGE   # forwards a WebSocket message\n  kind gateway\n  doc \"One entry point for an API: routing, authentication and rate limits before the services.\"\n}\n\ntype WAF extends HttpEdge {\n  doc \"A web application firewall: blocks malicious requests at the edge.\"\n}\n\n# Products.\n\ntype Fastly extends CDN {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"Fastly, the programmable CDN.\"\n}\n\ntype Akamai extends CDN {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"Akamai, the CDN and edge security platform.\"\n}\n\ntype nginx extends [Load Balancer] {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"nginx, the web server used as a reverse proxy and load balancer.\"\n}\n\ntype Envoy extends [Load Balancer] {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"Envoy, the L7 proxy behind most service meshes.\"\n}\n\ntype HAProxy extends [Load Balancer] {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"HAProxy, the TCP and HTTP load balancer.\"\n}\n\ntype Traefik extends [Load Balancer] {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"Traefik, the reverse proxy that configures itself from containers.\"\n}\n\ntype [Kubernetes Ingress] extends [Load Balancer] {\n  op write MESSAGE   # forwards a WebSocket message\n  doc \"A Kubernetes ingress controller: routes outside HTTP traffic to the cluster's services.\"\n}\n\ntype Kong extends [API Gateway] {\n  doc \"Kong, the open source API gateway built on nginx.\"\n}\n\ntype [Spring Cloud Gateway] extends [API Gateway] {\n  doc \"Spring Cloud Gateway, an API gateway for Spring services.\"\n}\n" },
  { path: "stdlib/external.proschi", source: "# Proschi standard library: systems you call but do not run. The rules are in\n# core.proschi.\n\nabstract type External {\n  kind external\n  protocol HTTP\n  op read  GET, HEAD, OPTIONS, TRACE, CONNECT\n  op write POST, PUT, PATCH, DELETE\n  status 100, 101, 102, 103\n  status 200, 201, 202, 203, 204, 205, 206, 207, 208, 226\n  status 300, 301, 302, 303, 304, 307, 308\n  status 400, 401, 402, 403, 404, 405, 406, 407, 408, 409, 410, 411, 412, 413, 414, 415, 416, 417, 418\n  status 421, 422, 423, 424, 425, 426, 428, 429, 431, 451\n  status 500, 501, 502, 503, 504, 505, 506, 507, 508, 510, 511\n  header Accept, Accept-Encoding, Accept-Language, Accept-Ranges, Age, Allow, Authorization\n  header Cache-Control, Connection, Content-Disposition, Content-Encoding, Content-Language\n  header Content-Length, Content-Range, Content-Type, Cookie, Date, ETag, Expires, Host\n  header If-Match, If-Modified-Since, If-None-Match, If-Range, If-Unmodified-Since, Last-Modified\n  header Link, Location, Origin, Range, Referer, Retry-After, Server, Set-Cookie, User-Agent, Vary\n  header Upgrade, WWW-Authenticate, Proxy-Authorization, Strict-Transport-Security, Content-Security-Policy\n  header Access-Control-Allow-Origin, Access-Control-Allow-Methods, Access-Control-Allow-Headers\n  header Access-Control-Allow-Credentials, Access-Control-Max-Age, Access-Control-Request-Method\n  header Forwarded, X-Forwarded-For, X-Forwarded-Host, X-Forwarded-Proto, X-Real-IP\n  header X-Request-Id, X-Correlation-Id, Traceparent, Tracestate, Idempotency-Key\n  header X-RateLimit-Limit, X-RateLimit-Remaining, X-RateLimit-Reset, RateLimit-Limit, RateLimit-Remaining, RateLimit-Reset\n  header X-API-Key, X-Content-Type-Options, X-Frame-Options, Sec-WebSocket-Key, Sec-WebSocket-Accept, Sec-WebSocket-Protocol\n  doc \"A system run by someone else that the design calls over its API.\"\n}\n\ntype [Third Party API] extends External {\n  op write SEND, NOTIFY\n  doc \"Another company's API, whose product does not matter.\"\n}\n\ntype [Payment Gateway] extends External {\n  op read  RETRIEVE\n  op write CHARGE, AUTHORIZE, CAPTURE, REFUND, VOID, PAYOUT\n  doc \"A payment provider: authorizes, captures and refunds card payments.\"\n}\n\ntype Stripe extends [Payment Gateway] {\n  doc \"Stripe, the payments API.\"\n}\n\ntype PayPal extends [Payment Gateway] {\n  doc \"PayPal, the online payments service.\"\n}\n\ntype Adyen extends [Payment Gateway] {\n  doc \"Adyen, the payments platform for cards and local payment methods.\"\n}\n\ntype Braintree extends [Payment Gateway] {\n  doc \"Braintree, PayPal's payments API for cards and wallets.\"\n}\n\ntype [Auth Service] extends External {\n  op read  VALIDATE, VERIFY, INTROSPECT, USERINFO, JWKS\n  op write LOGIN, LOGOUT, TOKEN, REFRESH, REVOKE, REGISTER\n  doc \"An identity provider: signs users in and issues and checks their tokens.\"\n}\n\ntype Auth0 extends [Auth Service] {\n  doc \"Auth0, the hosted identity provider.\"\n}\n\ntype Okta extends [Auth Service] {\n  doc \"Okta, the identity and single sign-on provider.\"\n}\n\nabstract type Notifier extends External {\n  op write SEND, NOTIFY\n  doc \"A provider that delivers messages to people: email, SMS or push notifications.\"\n}\n\ntype [Email Service] extends Notifier {\n  doc \"An email provider that sends the design's emails.\"\n}\n\ntype SendGrid extends [Email Service] {\n  doc \"SendGrid, Twilio's email API.\"\n}\n\ntype Mailgun extends [Email Service] {\n  doc \"Mailgun, the email API.\"\n}\n\ntype [SMS Service] extends Notifier {\n  doc \"An SMS provider that sends text messages.\"\n}\n\ntype Twilio extends [SMS Service] {\n  doc \"Twilio, the API for SMS, voice and messaging.\"\n}\n\ntype [Push Service] extends Notifier {\n  doc \"A push notification provider that delivers to phones.\"\n}\n\ntype APNs extends [Push Service] {\n  doc \"Apple Push Notification service, which delivers push notifications to Apple devices.\"\n}\n\ntype FCM extends [Push Service] {\n  doc \"Firebase Cloud Messaging, which delivers push notifications to Android, iOS and the web.\"\n}\n\ntype [Analytics Service] extends External {\n  op write TRACK, IDENTIFY, PAGE, SCREEN, ALIAS\n  doc \"A product analytics provider that receives usage events.\"\n}\n\ntype [Google Maps] extends External {\n  op read  GEOCODE, DIRECTIONS, DISTANCE, PLACES, ROUTES, TILES\n  doc \"Google Maps Platform: geocoding, directions, distances and map tiles.\"\n}\n\ntype OpenAI extends External {\n  op read  COMPLETE, CHAT, EMBED, MODERATE, TRANSCRIBE\n  doc \"OpenAI's API for language models and embeddings.\"\n}\n" },
  { path: "stdlib/messaging.proschi", source: "# Proschi standard library: queues and brokers, which take a message and\n# hand it on later. The rules are in core.proschi.\n\nabstract type Messaging {\n  op read  RECEIVE, SUBSCRIBE, UNSUBSCRIBE, READ\n  op write SEND, PUBLISH, EMIT, ENQUEUE, WRITE, ACK, NACK\n  doc \"A component that takes a message and hands it on later: a queue or a broker.\"\n}\n\ntype [Message Queue] extends Messaging {\n  kind queue\n  op read  DEQUEUE, PEEK, POLL\n  doc \"A queue of jobs: each message goes to one consumer, which deletes it when done.\"\n}\n\ntype [Message Broker] extends Messaging {\n  kind broker\n  op read  CONSUME, FETCH\n  op write PRODUCE\n  doc \"A broker of topics or streams: every subscriber gets each message, and the log can be replayed.\"\n}\n\ntype SQS extends [Message Queue] {\n  op read  ReceiveMessage, GetQueueAttributes, GetQueueUrl, ListQueues\n  op write SendMessage, SendMessageBatch, DeleteMessage, DeleteMessageBatch\n  op write ChangeMessageVisibility, ChangeMessageVisibilityBatch, PurgeQueue\n  op write CreateQueue, DeleteQueue, SetQueueAttributes\n  doc \"SQS, the managed message queue of AWS.\"\n}\n\ntype [Redis Queue] extends [Message Queue] {\n  protocol RESP\n  op read  XREAD, XREADGROUP, XRANGE, XLEN, XPENDING, LRANGE, LLEN, PSUBSCRIBE\n  op write XADD, XACK, XCLAIM, XAUTOCLAIM, XDEL, XTRIM, XGROUP, LPUSH, RPUSH, LPOP, RPOP, BLPOP, BRPOP, LMOVE, BLMOVE\n  doc \"A queue on Redis: a list, a stream or pub/sub channels.\"\n}\n\ntype ZeroMQ extends [Message Queue] {\n  op read  RECV\n  doc \"ZeroMQ, the brokerless messaging library of sockets.\"\n}\n\ntype Kafka extends [Message Broker] {\n  op read  Poll, OffsetFetch, ListOffsets, Metadata\n  op write Commit, OffsetCommit, AddPartitionsToTxn, EndTxn, DeleteRecords\n  op write CreateTopics, DeleteTopics, CreatePartitions\n  doc \"Apache Kafka, the distributed log of partitioned topics.\"\n}\n\ntype Redpanda extends Kafka {\n  doc \"Redpanda, a Kafka-compatible streaming platform written in C++.\"\n}\n\ntype RabbitMQ extends [Message Broker] {\n  protocol AMQP\n  op read  BasicGet, BasicConsume\n  op write BasicPublish, BasicAck, BasicNack, BasicReject, QueueDeclare, ExchangeDeclare, QueueBind, QueuePurge\n  doc \"RabbitMQ, the AMQP broker of exchanges and queues.\"\n}\n\ntype NATS extends [Message Broker] {\n  op read  REQUEST, SUB\n  op write PUB, REPLY\n  doc \"NATS, the lightweight messaging system, with JetStream for persistence.\"\n}\n\ntype [Apache Pulsar] extends [Message Broker] {\n  doc \"Apache Pulsar, the broker of topics with tiered storage.\"\n}\n\ntype ActiveMQ extends [Message Broker] {\n  doc \"Apache ActiveMQ, the JMS message broker.\"\n}\n" },
];
